package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getCumPct(Object)
 */
public class Frequency_getCumPct_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetCumPct_SumFreqZero_ReturnsNaN() {
        Frequency frequency = new Frequency();
        // sumFreq is 0 initially
        double result = frequency.getCumPct("anyValue");
        assertTrue("Expected NaN when sumFreq is 0", Double.isNaN(result));
    }

    @Test
    public void testGetCumPct_ValidValues_ReturnsCorrectCumulativePercentage() {
        Frequency frequency = new Frequency();

        // Add values to build frequency distribution
        // Values: A (1), B (2), C (3) -> Total Sum = 6
        frequency.addValue("A");
        frequency.addValue("B");
        frequency.addValue("B");
        frequency.addValue("C");
        frequency.addValue("C");
        frequency.addValue("C");

        // Cumulative frequencies:
        // A: 1
        // B: 1 + 2 = 3
        // C: 3 + 3 = 6

        // Test A: 1/6
        assertEquals(1.0 / 6.0, frequency.getCumPct("A"), DELTA);

        // Test B: 3/6
        assertEquals(3.0 / 6.0, frequency.getCumPct("B"), DELTA);

        // Test C: 6/6
        assertEquals(6.0 / 6.0, frequency.getCumPct("C"), DELTA);
    }

    @Test
    public void testGetCumPct_NonExistentValue_ReturnsZero() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);

        // sumFreq = 2
        // getCumFreq("non-existent") = 0
        // 0 / 2 = 0.0
        assertEquals(0.0, frequency.getCumPct("non-existent"), DELTA);
    }

    @Test
    public void testGetCumPct_WithIntegers() {
        Frequency frequency = new Frequency();
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(30);

        // Total = 3
        // CumFreq(10) = 1 -> 1/3
        // CumFreq(20) = 2 -> 2/3
        // CumFreq(30) = 3 -> 3/3

        assertEquals(1.0 / 3.0, frequency.getCumPct(10), DELTA);
        assertEquals(2.0 / 3.0, frequency.getCumPct(20), DELTA);
        assertEquals(1.0, frequency.getCumPct(30), DELTA);
    }

    @Test
    public void testGetCumPct_AfterClear() {
        Frequency frequency = new Frequency();
        frequency.addValue("test");
        frequency.clear();

        // After clear, sumFreq is 0
        assertTrue(Double.isNaN(frequency.getCumPct("test")));
    }
}
